@@ -572,6 +579,22 @@ function citationLine(c) {
   return el("p", `cites ${c.reference_id}: ${c.title}${who}${c.year ? ` (${c.year})` : ""} · ${c.locator} · ${c.version}`, { class: "hint citation" });
 }

+// an imported result's own Reference review made cheap (ADR-0022 point 3): the rules an agent's import would meet, and
+// the Verifier's "unchecked against the source" marks on what rests on it, each naming the dependent and its snapshot
+function importNotes(info) {
+  const out = el("div", null, { class: "import-notes" });
+  if (!info) return out;
+  const rules = info.would_meet_trust_rule || [];
+  if (rules.length) out.append(el("p", `an agent's import: it would meet trust rule ${rules.join(", ")} had you imported it, and counts only once you review it`, { class: "hint" }));
+  const marks = info.unchecked || [];
+  if (marks.length) {
+    const list = el("ul", null, { class: "unchecked-marks" });
+    for (const m of marks) list.append(el("li", `${m.dependent}, snapshot v${m.snapshot}${m.current ? "" : " (superseded)"}: ${m.note}`));
+    out.append(el("p", "unchecked against the source by the Verifier of:", { class: "unchecked-head" }), list);
+  }
+  return out;
+}
